children.input:
{
  "project_id": "5eb6b210bd534bc5a2c9",
  "name": "secure_multi_tenant_documents",
  "query": "create table if not exists public.memberships (
  user_id uuid not null,
  org_id uuid not null,
  role text not null,
  primary key (user_id, org_id),
  constraint memberships_role_check check (role in ('viewer', 'editor', 'admin'))
);

create table if not exists public.documents (
  id uuid primary key,
  org_id uuid not null,
  owner_id uuid not null,
  title text,
  body text,
  deleted_at timestamptz
);

create table if not exists public.document_audit (
  id uuid primary key,
  document_id uuid not null,
  actor_id uuid not null,
  action text not null,
  ts timestamptz not null
);

create schema if not exists private;
revoke all on schema private from public;

create index if not exists memberships_user_org_role_idx
  on public.memberships (user_id, org_id, role);
create index if not exists documents_active_org_idx
  on public.documents (org_id) where deleted_at is null;
create index if not exists documents_active_owner_idx
  on public.documents (owner_id) where deleted_at is null;
create index if not exists document_audit_document_ts_idx
  on public.document_audit (document_id, ts desc);

alter table public.memberships enable row level security;
alter table public.documents enable row level security;
alter table public.document_audit enable row level security;

drop policy if exists "Members can view their own memberships" on public.memberships;
create policy "Members can view their own memberships"
on public.memberships for select to authenticated
using (user_id = (select auth.uid()));

drop policy if exists "Members can read active documents" on public.documents;
create policy "Members can read active documents"
on public.documents for select to authenticated
using (
  deleted_at is null
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role in ('viewer', 'editor', 'admin')
  )
);

drop policy if exists "Editors can insert owned documents" on public.documents;
create policy "Editors can insert owned documents"
on public.documents for insert to authenticated
with check (
  deleted_at is null
  and owner_id = (select auth.uid())
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'editor'
  )
);

drop policy if exists "Editors can update owned active documents" on public.documents;
create policy "Editors can update owned active documents"
on public.documents for update to authenticated
using (
  deleted_at is null
  and owner_id = (select auth.uid())
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'editor'
  )
)
with check (
  owner_id = (select auth.uid())
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'editor'
  )
);

drop policy if exists "Editors can soft delete owned active documents" on public.documents;
create policy "Editors can soft delete owned active documents"
on public.documents for delete to authenticated
using (
  deleted_at is null
  and owner_id = (select auth.uid())
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'editor'
  )
);

drop policy if exists "Admins can update active documents" on public.documents;
create policy "Admins can update active documents"
on public.documents for update to authenticated
using (
  deleted_at is null
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'admin'
  )
)
with check (
  org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'admin'
  )
);

drop policy if exists "Admins can soft delete active documents" on public.documents;
create policy "Admins can soft delete active documents"
on public.documents for delete to authenticated
using (
  deleted_at is null
  and org_id in (
    select m.org_id
    from public.memberships m
    where m.user_id = (select auth.uid())
      and m.role = 'admin'
  )
);

create or replace function private.write_document_audit()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  insert into public.document_audit (id, document_id, actor_id, action, ts)
  values (
    gen_random_uuid(),
    coalesce(new.id, old.id),
    (select auth.uid()),
    case
      when tg_op = 'INSERT' then 'insert'
      when old.deleted_at is null and new.deleted_at is not null then 'soft_delete'
      else 'update'
    end,
    clock_timestamp()
  );
  return coalesce(new, old);
end;
$$;

create or replace function private.soft_delete_document()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $$
begin
  update public.documents
  set deleted_at = clock_timestamp()
  where id = old.id
    and deleted_at is null;
  return null;
end;
$$;

revoke all on function private.write_document_audit() from public;
revoke all on function private.soft_delete_document() from public;

drop trigger if exists document_audit_after_insert on public.documents;
create trigger document_audit_after_insert
after insert on public.documents
for each row execute function private.write_document_audit();

drop trigger if exists document_audit_after_update on public.documents;
create trigger document_audit_after_update
after update on public.documents
for each row execute function private.write_document_audit();

drop trigger if exists documents_soft_delete_before_delete on public.documents;
create trigger documents_soft_delete_before_delete
before delete on public.documents
for each row execute function private.soft_delete_document();

grant select on public.memberships to authenticated;
grant select, insert, update, delete on public.documents to authenticated;
revoke all on public.document_audit from anon, authenticated;
"
}

